#include "changelog.h"

#include <sstream>

#ifdef CIMA_HAS_CHANGELOG
#include "changelog_data.h"  // generated by CMake from CHANGELOG.md: kChangelog[], 0-terminated
#endif

namespace {
std::string trim(const std::string& s) {
    const size_t a = s.find_first_not_of(" \t\r\n");
    if (a == std::string::npos) return std::string();
    const size_t b = s.find_last_not_of(" \t\r\n");
    return s.substr(a, b - a + 1);
}
}  // namespace

std::vector<ChangeEntry> parseChangelog(const std::string& md) {
    std::vector<ChangeEntry> out;
    std::istringstream in(md);
    std::string line;
    bool inItem = false;
    while (std::getline(in, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.compare(0, 3, "## ") == 0) {
            ChangeEntry e;
            std::string head = trim(line.substr(3));
            const size_t dash = head.find(" - ");
            if (dash != std::string::npos) {
                e.date = trim(head.substr(dash + 3));
                head = trim(head.substr(0, dash));
            }
            if (!head.empty() && (head[0] == 'v' || head[0] == 'V')) head.erase(0, 1);
            e.version = head;
            out.push_back(e);
            inItem = false;
            continue;
        }
        if (out.empty()) continue;  // the title and notes above the first version
        const std::string t = trim(line);
        if (t.empty()) {
            inItem = false;
            continue;
        }
        if (t.compare(0, 2, "- ") == 0 || t.compare(0, 2, "* ") == 0) {
            out.back().items.push_back(trim(t.substr(2)));
            inItem = true;
        } else if (inItem && (line[0] == ' ' || line[0] == '\t')) {
            out.back().items.back() += " " + t;  // a change written over several lines
        }
    }
    return out;
}

const std::vector<ChangeEntry>& changelog() {
#ifdef CIMA_HAS_CHANGELOG
    static const std::vector<ChangeEntry> entries = parseChangelog(reinterpret_cast<const char*>(kChangelog));
#else
    static const std::vector<ChangeEntry> entries;
#endif
    return entries;
}
